<div class="panel overflow-hidden"><div class="p-5 font-bold">Subject-wise Result Records</div><form class="px-5 pb-4 flex flex-wrap gap-2"><select name="student_id" class="field max-w-xs"><option value="">All Students</option><?php $__currentLoopData = $students; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $s): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($s->id); ?>" <?php if(request('student_id')==$s->id): echo 'selected'; endif; ?>><?php echo e($s->student_id); ?> · <?php echo e($s->name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><input name="exam_name" value="<?php echo e(request('exam_name')); ?>" placeholder="Exam name" class="field max-w-xs"><input name="exam_year" value="<?php echo e(request('exam_year')); ?>" placeholder="Year" class="field max-w-28"><button class="btn btn-primary">Filter</button></form><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-slate-50"><tr><th class="p-3 text-left">Student</th><th class="p-3">Exam</th><th class="p-3 text-left">Subject</th><th class="p-3">Marks</th><th class="p-3">Grade</th><th class="p-3">GP</th><th class="p-3">Action</th></tr></thead><tbody><?php $__empty_1 = true; $__currentLoopData = $results; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $r): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><tr class="border-t"><td class="p-3"><?php echo e($r->student?->student_id); ?><div class="text-xs muted"><?php echo e($r->student?->name); ?></div></td><td class="p-3 text-center"><?php echo e($r->exam_name); ?><div class="text-xs muted"><?php echo e($r->exam_year); ?></div></td><td class="p-3"><?php echo e($r->subject_name); ?><div class="text-xs muted"><?php echo e($r->subject_code); ?></div></td><td class="p-3 text-center"><?php echo e(number_format($r->marks,2)); ?> / <?php echo e(number_format($r->full_marks??100,2)); ?></td><td class="p-3 text-center"><?php echo e($r->letter_grade); ?></td><td class="p-3 text-center"><?php echo e(number_format($r->grade_point,2)); ?></td><td class="p-3 text-center"><form method="POST" action="<?php echo e(route('results.destroy',$r)); ?>" onsubmit="return confirm('Delete this result?')"><?php echo csrf_field(); ?> <?php echo method_field('DELETE'); ?><button class="text-rose-600">Delete</button></form></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><tr><td colspan="7" class="p-8 text-center muted">No results found.</td></tr><?php endif; ?></tbody></table></div><div class="p-4"><?php echo e($results->links()); ?></div></div>
<p class="text-xs muted mt-4">Grade is calculated from percentage of Full Marks. Confirm the official BTEB grading policy before production use. GPA = Σ(Credit × Grade Point) ÷ Σ(Credit).</p>
<script>const tech=document.getElementById('techSelect'),sem=document.getElementById('semSelect'),rows=[...document.querySelectorAll('.mark-row')];function filterRows(){let n=0;rows.forEach(r=>{const show=tech.value&&sem.value&&r.dataset.tech===tech.value&&r.dataset.sem===sem.value;r.classList.toggle('hidden',!show);if(show)n++});document.getElementById('studentCount').textContent=n+' students';document.querySelectorAll('.mark-input').forEach(i=>i.max=document.getElementById('fullMarks').value||100)}tech.addEventListener('change',filterRows);sem.addEventListener('change',filterRows);document.getElementById('fullMarks').addEventListener('input',()=>{const max=Number(document.getElementById('fullMarks').value)||1;document.querySelectorAll('.mark-input').forEach(i=>{i.max=max});filterRows()});document.getElementById('markSearch').addEventListener('input',e=>{let q=e.target.value.toLowerCase();rows.forEach(r=>{if(!r.classList.contains('hidden'))r.style.display=r.innerText.toLowerCase().includes(q)?'':'none'})});function fillMarks(v){rows.filter(r=>!r.classList.contains('hidden')).forEach(r=>r.querySelector('input').value=v)}function clearMarks(){document.querySelectorAll('.mark-input').forEach(i=>i.value='')}document.getElementById('marksForm').addEventListener('submit',e=>{if(!rows.some(r=>!r.classList.contains('hidden'))){e.preventDefault();alert('Select Technology and Semester first.')}});</script>
